  tasks:'<path d="M8 4H5a1 1 0 0 0-1 1v15a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1V5a1 1 0 0 0-1-1h-3"/><rect x="8" y="2" width="8" height="4" rx="1.5"/><path d="m8 13 3 3 5-6"/>',
  documents:'<path d="M14 3H5v18h14V8l-5-5zm0 0v5h5M8 11h4m-4 3h3"/><circle cx="15" cy="15" r="2.5"/><path d="m13.5 17-1 4 2.5-1 2.5 1-1-4"/>',
  billing:'<path d="M5 3h14v18l-3-2-4 2-4-2-3 2V3zM9 7h6m-6 3h6m-6-3c6 0 6 6 0 6l5 4"/>',
  invoices:'<path d="M5 3h14v18l-3-2-4 2-4-2-3 2V3zM9 7h6m-6 4h6m-6 4h3"/>',
  payments:'<rect x="2" y="5" width="20" height="14" rx="2"/><path d="M2 10h20m-15 5h3m6 0 2 2 3-4"/>',
  expenses:'<path d="M5 3h14v18l-3-2-4 2-4-2-3 2V3zM9 8h6m-6 4h6m-6 4h3"/>',
  reports:'<path d="M4 3v18h17M8 16v-5m5 5V7m5 9V4"/>',
  settings:'<path d="m9 3-1 3-3 1-2 4 2 2v4l4 3 3-1 3 1 4-3v-4l2-2-2-4-3-1-1-3z"/><circle cx="12" cy="12" r="3"/>',
  search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
  sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',
  moon:'<path d="M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11z"/>',
  menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
  plus:'<path d="M12 5v14M5 12h14"/>',
  arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',
  download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
  bell:'<path d="M5 17h14l-2-4V9a5 5 0 0 0-10 0v4zm5 3h4"/>',
  notes:'<path d="M10 4H4v17h16v-7m-7-3-5 2 2-5 9-6 3 3-9 6zm4-7 3 3M8 17h7"/>',
  edit:'<path d="m14 5 5 5M4 20l5-1L21 7a2 2 0 0 0-4-4L5 15l-1 5z"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
